class MathGraph:
    """Own and evaluate value, operation and output nodes."""

    def __init__(self) -> None:
        """Create an empty graph."""
        self._nodes: dict[str, GraphNode] = {}
        self._next_id = 1

    def _add_node(self, node: GraphNode) -> str:
        """Add a graph node and return its stable identifier."""
        node_id = f"node-{self._next_id}"
        self._next_id += 1
        self._nodes[node_id] = node
        return node_id

    def add_value(self, math_type: MathType, components: tuple[float, ...]) -> str:
        """Add a typed value node to the graph."""
        _validate_components(math_type, components)
        return self._add_node(ValueNode(math_type, tuple(components)))

    def add_operation(self, operation: Operation) -> str:
        """Add a wired operation node to the graph."""
        if operation in GENERATOR_OPERATIONS:
            raise ValueError(
                f"{operation.value} has no wired inputs; use add_generator instead"
            )
        return self._add_node(OperationNode(operation))

    def add_generator(
        self,
        operation: Operation,
        parameters: tuple[tuple[float, ...], ...],
        *,
        rotation_order: str | None = None,
    ) -> str:
        """Add a parameter node (Look At, Perspective, ...) to the graph."""
        if operation not in GENERATOR_OPERATIONS:
            raise ValueError(
                f"{operation.value} has no typed-in parameters; use add_operation instead"
            )
        parameter_types = OPERATION_PARAMETER_TYPES[operation]
        if len(parameters) != len(parameter_types):
            raise ValueError(
                f"{operation.value} needs {len(parameter_types)} parameters, "
                f"got {len(parameters)}"
            )
        for parameter_type, components in zip(parameter_types, parameters, strict=True):
            _validate_components(parameter_type, components)
        if operation is Operation.TRANSFORM and rotation_order is None:
            rotation_order = DEFAULT_TRANSFORM_ROTATION_ORDER
        if operation is Operation.TRANSFORM:
            assert rotation_order is not None
            _validate_transform_rotation_order(rotation_order)
        elif rotation_order is not None:
            raise ValueError(f"{operation.value} does not use a rotation order")
        return self._add_node(
            GeneratorNode(operation, [tuple(p) for p in parameters], rotation_order)
        )

    def set_generator_parameter(
        self, node_id: str, parameter_index: int, components: tuple[float, ...]
    ) -> None:
        """Replace one parameter's components on a generator node."""
        node = self._nodes[node_id]
        if not isinstance(node, GeneratorNode):
            raise ValueError("Only generator nodes store editable parameters")
        parameter_type = OPERATION_PARAMETER_TYPES[node.operation][parameter_index]
        _validate_components(parameter_type, components)
        node.parameters[parameter_index] = tuple(components)

    def set_generator_rotation_order(self, node_id: str, rotation_order: str) -> None:
        """Set the rotation order stored by a Transform generator."""
        node = self._nodes[node_id]
        if (
            not isinstance(node, GeneratorNode)
            or node.operation is not Operation.TRANSFORM
        ):
            raise ValueError("Only Transform generators store a rotation order")
        _validate_transform_rotation_order(rotation_order)
        node.rotation_order = rotation_order

    def set_value(self, node_id: str, components: tuple[float, ...]) -> None:
        """Replace the components stored by a value node."""
        node = self._nodes[node_id]
        if not isinstance(node, ValueNode):
            raise ValueError("Only value nodes store editable components")
        _validate_components(node.math_type, components)
        node.components = tuple(components)

    def value_components(self, node_id: str) -> tuple[float, ...]:
        """Return the exact components stored by a value node."""
        node = self._nodes[node_id]
        if not isinstance(node, ValueNode):
            raise ValueError("Only value nodes store editable components")
        return node.components

    def generator_parameters(self, node_id: str) -> tuple[tuple[float, ...], ...]:
        """Return an immutable snapshot of a generator node's parameters."""
        node = self._nodes[node_id]
        if not isinstance(node, GeneratorNode):
            raise ValueError("Only generator nodes store editable parameters")
        return tuple(node.parameters)

    def generator_rotation_order(self, node_id: str) -> str:
        """Return the rotation order stored by a Transform generator."""
        node = self._nodes[node_id]
        if (
            not isinstance(node, GeneratorNode)
            or node.operation is not Operation.TRANSFORM
        ):
            raise ValueError("Only Transform generators store a rotation order")
        assert node.rotation_order is not None
        return node.rotation_order

    def add_output(self) -> str:
        """Add an output node to the graph."""
        return self._add_node(OutputNode())

    def add_literal(self, value: MathValue) -> str:
        """Add a pre-computed, non-editable value node to the graph."""
        return self._add_node(LiteralNode(value))

    def set_literal(self, node_id: str, value: MathValue) -> None:
        """Replace the value stored by a literal node."""
        node = self._nodes[node_id]
        if not isinstance(node, LiteralNode):
            raise ValueError("Only literal nodes store replaceable values")
        node.value = value

    def add_mesh_viewer(self) -> str:
        """Add a mesh viewer sink node to the graph."""
        return self._add_node(MeshViewerNode())

    def connect(self, source_id: str, target_id: str, input_index: int) -> None:
        """Connect a source node to an input on another node."""
        target = self._nodes[target_id]
        if isinstance(target, (ValueNode, LiteralNode, GeneratorNode)):
            raise ValueError("This node type does not have inputs")
        target.inputs[input_index] = source_id

    def disconnect(self, target_id: str, input_index: int) -> None:
        """Remove one input wire without deleting either node."""
        target = self._nodes[target_id]
        if isinstance(target, (ValueNode, LiteralNode, GeneratorNode)):
            raise ValueError("This node type does not have inputs")
        target.inputs.pop(input_index, None)

    def remove_node(self, node_id: str) -> None:
        """Delete a node and clear any downstream inputs that referenced it."""
        del self._nodes[node_id]
        for node in self._nodes.values():
            if isinstance(node, (ValueNode, LiteralNode, GeneratorNode)):
                continue
            for input_index, source_id in list(node.inputs.items()):
                if source_id == node_id:
                    del node.inputs[input_index]

    def evaluate(self, node_id: str) -> MathValue:
        """Evaluate a graph node and all the inputs below it."""
        return self._evaluate(node_id, set())

    def evaluate_mesh_viewer(self, node_id: str) -> MeshViewerInputs:
        """Evaluate a Mesh Viewer node's inputs, ready to merge and render."""
        node = self._nodes[node_id]
        if not isinstance(node, MeshViewerNode):
            raise ValueError("Only mesh viewer nodes can be evaluated this way")
        if 0 not in node.inputs:
            raise GraphError("Mesh Viewer needs input Vertices")
        if 1 not in node.inputs:
            raise GraphError("Mesh Viewer needs input Faces")

        vertices = self._evaluate(node.inputs[0], set())
        faces = self._evaluate(node.inputs[1], set())
        uvs = self._evaluate(node.inputs[2], set()) if 2 in node.inputs else None
        normals = self._evaluate(node.inputs[3], set()) if 3 in node.inputs else None
        colour = self._evaluate(node.inputs[4], set()) if 4 in node.inputs else None

        if not isinstance(vertices, VertexArray):
            raise GraphError("Mesh Viewer Vertices needs a Vertices input")
        if not isinstance(faces, FaceArray):
            raise GraphError("Mesh Viewer Faces needs a Faces input")
        if uvs is not None and not isinstance(uvs, UVArray):
            raise GraphError("Mesh Viewer UVs needs a UVs input")
        if normals is not None and not isinstance(normals, NormalArray):
            raise GraphError("Mesh Viewer Normals needs a Normals input")
        if colour is not None and not isinstance(colour, Vec4):
            raise GraphError("Mesh Viewer Colour needs a Vec4 input")

        validate_mesh_arrays(vertices, faces, uvs, normals)
        return MeshViewerInputs(vertices, faces, uvs, normals, colour)

    def _evaluate(self, node_id: str, active_nodes: set[str]) -> MathValue:
        """Evaluate a node whilst tracking the current recursion path."""
        if node_id in active_nodes:
            raise GraphError("The graph contains a cycle")
        active_nodes.add(node_id)

        node = self._nodes[node_id]
        try:
            if isinstance(node, ValueNode):
                return VALUE_CLASSES[node.math_type](*node.components)
            if isinstance(node, LiteralNode):
                return node.value
            if isinstance(node, GeneratorNode):
                parameter_types = OPERATION_PARAMETER_TYPES[node.operation]
                values = tuple(
                    VALUE_CLASSES[parameter_type](*components)
                    for parameter_type, components in zip(
                        parameter_types, node.parameters, strict=True
                    )
                )
                if node.operation is Operation.TRANSFORM:
                    return apply_operation(
                        node.operation,
                        *values,
                        rotation_order=self.generator_rotation_order(node_id),
                    )
                return apply_operation(node.operation, *values)
            if isinstance(node, OutputNode):
                if 0 not in node.inputs:
                    raise GraphError("Output needs input Value")
                return self._evaluate(node.inputs[0], active_nodes)
            if isinstance(node, MeshViewerNode):
                raise GraphError("Mesh Viewer has no single output value")

            for input_index in range(OPERATION_ARITY[node.operation]):
                if input_index not in node.inputs:
                    input_name = OPERATION_INPUT_NAMES[node.operation][input_index]
                    raise GraphError(f"{node.operation.value} needs input {input_name}")

            values = tuple(
                self._evaluate(node.inputs[input_index], active_nodes)
                for input_index in range(OPERATION_ARITY[node.operation])
            )
            return apply_operation(node.operation, *values)
        finally:
            active_nodes.remove(node_id)
)

_OBJ_PARSE_ERRORS = (
    ObjParseVertexError,
    ObjParseNormalError,
    ObjParseUVError,
    ObjParseFaceError,
)

DEFAULT_EXAMPLE_PATH = (
    Path(__file__).resolve().parent / "examples" / "vec3_multiply_demo.json"
)


class MathNodeScene(QGraphicsScene):
    """Graphics scene which keeps visible wires and the maths graph in sync."""

    modifiedChanged = Signal(bool)

    def __init__(self, parent: QWidget | None = None) -> None:
        """Create an empty node graph canvas."""
        super().__init__(parent)
        self.setSceneRect(-1800.0, -1200.0, 3600.0, 2400.0)
        self.graph = MathGraph()
        self.nodes: dict[str, BaseNodeItem] = {}
        self.connections: list[ConnectionItem] = []
        self._drag_source: PortItem | None = None
        self._preview_connection: QGraphicsPathItem | None = None
        self._insertion_index = 0
        self.modified = False
        self._loading = False

    def set_modified(self, modified: bool) -> None:
        """Set the document state and notify listeners when it changes."""
        if (modified and self._loading) or self.modified == modified:
            return
        self.modified = modified
        self.modifiedChanged.emit(modified)

    def mark_modified(self) -> None:
        """Flag the graph as having unsaved changes."""
        self.set_modified(True)

    def mark_clean(self) -> None:
        """Flag the graph as matching the document on disk."""
        self.set_modified(False)

    def _next_position(self) -> QPointF:
        """Return a slightly offset position for the next palette node."""
        offset = float((self._insertion_index % 8) * 34)
        self._insertion_index += 1
        return QPointF(-300.0 + offset, -190.0 + offset)

    def add_value_node(
        self,
        math_type: MathType,
        position: QPointF | None = None,
        components: tuple[float, ...] | None = None,
    ) -> ValueNodeItem:
        """Add an editable maths value node to the canvas."""
        node_components = (
            components if components is not None else default_components(math_type)
        )
        node_id = self.graph.add_value(math_type, node_components)
        node = ValueNodeItem(
            node_id,
            math_type,
            node_components,
            lambda values, value_node_id=node_id: self._value_changed(
                value_node_id, values
            ),
        )
        self.addItem(node)
        node.setPos(position if position is not None else self._next_position())
        self.nodes[node_id] = node
        self.mark_modified()
        return node

    def add_operation_node(
        self,
        operation: Operation,
        position: QPointF | None = None,
    ) -> OperationNodeItem:
        """Add an operation node to the canvas."""
        node_id = self.graph.add_operation(operation)
        node = OperationNodeItem(node_id, operation)
        self.addItem(node)
        node.setPos(position if position is not None else self._next_position())
        self.nodes[node_id] = node
        self.mark_modified()
        return node

    def add_generator_node(
        self,
        operation: Operation,
        position: QPointF | None = None,
        parameters: tuple[tuple[float, ...], ...] | None = None,
        rotation_order: str | None = None,
    ) -> GeneratorNodeItem:
        """Add a parameter node (Look At, Perspective, ...) to the canvas."""
        node_parameters = (
            parameters
            if parameters is not None
            else default_generator_parameters(operation)
        )
        node_id = self.graph.add_generator(
            operation, node_parameters, rotation_order=rotation_order
        )
        node = GeneratorNodeItem(
            node_id,
            operation,
            node_parameters,
            lambda parameter_index,
            values,
            generator_node_id=node_id: self._generator_changed(
                generator_node_id, parameter_index, values
            ),
            rotation_order=(
                self.graph.generator_rotation_order(node_id)
                if operation is Operation.TRANSFORM
                else None
            ),
            on_rotation_order_change=lambda order,
            generator_node_id=node_id: self._generator_rotation_order_changed(
                generator_node_id, order
            ),
        )
        self.addItem(node)
        node.setPos(position if position is not None else self._next_position())
        self.nodes[node_id] = node
        self.mark_modified()
        return node

    def add_output_node(self, position: QPointF | None = None) -> OutputNodeItem:
        """Add a result node to the canvas."""
        node_id = self.graph.add_output()
        node = OutputNodeItem(node_id)
        self.addItem(node)
        node.setPos(position if position is not None else self._next_position())
        self.nodes[node_id] = node
        self.mark_modified()
        return node

    def add_obj_loader_node(self, position: QPointF | None = None) -> ObjLoaderNodeItem:
        """Add an Obj Loader node with four empty array outputs."""
        array_node_ids = (
            self.graph.add_literal(VertexArray(())),
            self.graph.add_literal(FaceArray(())),
            self.graph.add_literal(UVArray(())),
            self.graph.add_literal(NormalArray(())),
        )
        node = ObjLoaderNodeItem(
            array_node_ids[0], array_node_ids, self._load_obj_into_node
        )
        self.addItem(node)
        node.setPos(position if position is not None else self._next_position())
        self.nodes[node.node_id] = node
        self.mark_modified()
        return node

    def _load_obj_into_node(self, item: ObjLoaderNodeItem) -> None:
        """Prompt for an Obj file and load it into an existing loader node."""
        parent_widget = self.views()[0] if self.views() else None
        path, _name_filter = QFileDialog.getOpenFileName(
            parent_widget, "Load Obj", "", "Obj Files (*.obj)"
        )
        if not path:
            return
        try:
            obj = Obj()
            if not obj.load(path):
                raise GraphError(f"Could not parse {Path(path).name}")
            vertices, faces, uvs, normals = arrays_from_obj(obj)
        except (GraphError, OSError, ValueError, *_OBJ_PARSE_ERRORS) as error:
            item.set_status(str(error) or type(error).__name__, is_error=True)
            return

        vertices_id, faces_id, uv_id, normals_id = item.array_node_ids
        self.graph.set_literal(vertices_id, vertices)
        self.graph.set_literal(faces_id, faces)
        self.graph.set_literal(uv_id, uvs)
        self.graph.set_literal(normals_id, normals)
        item.set_status(
            f"{Path(path).name}: {len(vertices.values)} verts, "
            f"{len(faces.triangles)} faces"
        )
        self.update_outputs()

    def add_mesh_viewer_node(
        self,
        position: QPointF | None = None,
        shading_mode: str = SHADING_SOLID,
        wireframe: bool = False,
    ) -> MeshViewerNodeItem:
        """Add a mesh viewer sink node to the canvas."""
        node_id = self.graph.add_mesh_viewer()
        node = MeshViewerNodeItem(
            node_id,
            lambda viewer_id=node_id: self._mesh_viewer_config_changed(viewer_id),
            shading_mode=shading_mode,
            wireframe=wireframe,
        )
        self.addItem(node)
        node.setPos(position if position is not None else self._next_position())
        self.nodes[node_id] = node
        self.mark_modified()
        return node

    def _mesh_viewer_config_changed(self, node_id: str) -> None:
        """Refresh display-only settings without rebuilding valid geometry."""
        self.mark_modified()
        node = self.nodes.get(node_id)
        if not isinstance(node, MeshViewerNodeItem):
            return
        mesh_inputs = node.render_state.mesh_inputs
        diffuse_needs_normals = node.render_state.shading_mode == SHADING_DIFFUSE and (
            mesh_inputs is None
            or mesh_inputs.normals is None
            or not mesh_inputs.normals.values
        )
        if mesh_inputs is None or diffuse_needs_normals:
            self.update_outputs()

    def _value_changed(self, node_id: str, components: tuple[float, ...]) -> None:
        """Update a graph value after a spin box changes."""
        self.graph.set_value(node_id, components)
        self.update_outputs()

    def _generator_changed(
        self, node_id: str, parameter_index: int, components: tuple[float, ...]
    ) -> None:
        """Update a graph generator parameter after a spin box changes."""
        self.graph.set_generator_parameter(node_id, parameter_index, components)
        self.update_outputs()

    def _generator_rotation_order_changed(
        self, node_id: str, rotation_order: str
    ) -> None:
        """Update a Transform generator after its rotation order changes."""
        self.graph.set_generator_rotation_order(node_id, rotation_order)
        self.update_outputs()

    def _item_for_node_id(self, graph_node_id: str) -> BaseNodeItem:
        """Return the graphics item that owns a graph node id."""
        for node in self.nodes.values():
            if graph_node_id in node.owned_node_ids():
                return node
        raise KeyError(graph_node_id)

    def _output_port_for_node_id(self, graph_node_id: str) -> PortItem:
        """Return the output socket that sources a given graph node id."""
        item = self._item_for_node_id(graph_node_id)
        for port in item.output_ports:
            if port.graph_node_id == graph_node_id:
                return port
        raise KeyError(graph_node_id)

    def connect_ports(self, source: PortItem, target: PortItem) -> ConnectionItem:
        """Connect an output socket to an input, replacing its previous wire."""
        if not source.is_output or target.is_output or target.input_index is None:
            raise GraphError("Connections must run from an output to an input")
        if source.node is target.node:
            raise GraphError("A node cannot connect directly to itself")

        for old_connection in list(target.connections):
            self._remove_connection(old_connection)
        self.graph.connect(
            source.graph_node_id, target.node.node_id, target.input_index
        )
        connection = ConnectionItem(source, target)
        self.addItem(connection)
        self.connections.append(connection)
        target.colour = source.colour
        target.setBrush(QBrush(source.colour))
        connection.update_path()
        self.update_outputs()
        return connection

    def _remove_connection(self, connection: ConnectionItem) -> None:
        """Remove a visible wire before replacing an input connection."""
        connection.detach()
        self.connections.remove(connection)
        self.removeItem(connection)

    def delete_selected(self) -> None:
        """Remove the selected nodes, then any additionally selected wires."""
        selected_nodes = [
            item for item in self.selectedItems() if isinstance(item, BaseNodeItem)
        ]
        selected_connections = [
            item for item in self.selectedItems() if isinstance(item, ConnectionItem)
        ]
        if not selected_nodes and not selected_connections:
            return
        for node in selected_nodes:
            self._delete_node(node)
        for connection in selected_connections:
            if connection in self.connections:
                self._disconnect(connection)
        self.update_outputs()

    def _delete_node(self, node: BaseNodeItem) -> None:
        """Remove a node, detaching its wires and dropping it from the graph."""
        if isinstance(node, MeshViewerNodeItem):
            node.close_popup()
        ports = [*node.input_ports, *node.output_ports]
        for port in ports:
            for connection in list(port.connections):
                self._remove_connection(connection)
        for owned_id in node.owned_node_ids():
            self.graph.remove_node(owned_id)
        del self.nodes[node.node_id]
        self.removeItem(node)

    def _disconnect(self, connection: ConnectionItem) -> None:
        """Remove one wire and its underlying graph connection."""
        self.graph.disconnect(
            connection.target.node.node_id, connection.target.input_index
        )
        self._remove_connection(connection)

    def clear_graph(self) -> None:
        """Remove all visible items and start a fresh calculation graph."""
        for node in self.nodes.values():
            if isinstance(node, MeshViewerNodeItem):
                node.close_popup()
        self.clear()
        self.graph = MathGraph()
        self.nodes.clear()
        self.connections.clear()
        self._drag_source = None
        self._preview_connection = None
        self._insertion_index = 0
        self.mark_clean()

    def load_example(self) -> None:
        """Load the bundled Vec3 component-multiply example graph."""
        self.load_from_file(DEFAULT_EXAMPLE_PATH)

    def to_dict(self) -> dict[str, object]:
